import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type TwitterLogoAnimationProps = Record<string, any>;

const TwitterLogoAnimation: React.FC<TwitterLogoAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  iconColor = "#1DA1F2",
  durationInSeconds = 5,
  logoSize = 400,
  floatIntensity = 20,
}) => {
  
  // Load standard font just in case, satisfying structure requirements
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Calculate derived values
  const durationInFrames = durationInSeconds * fps;
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation 1: Entrance Pop (Spring)
  const entranceSpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 0.8,
    },
    durationInFrames: 45, // Explicit duration for spring curve stretching
  });

  // Animation 2: Floating/Breathing Idle Loop
  // Starts after entrance, loops continuously
  const floatOffset = Math.sin(frame / 20) * floatIntensity;
  
  // Animation 3: Fly Away Exit (Moves out of canvas to top-right)
  const exitStartFrame = durationInFrames - 25;
  
  const flyX = interpolate(
    frame,
    [exitStartFrame, durationInFrames],
    [0, width / 2 + logoSize], // Fly off-screen right
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const flyY = interpolate(
    frame,
    [exitStartFrame, durationInFrames],
    [0, -height / 2 - logoSize], // Fly off-screen top
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const flyRotate = interpolate(
    frame,
    [exitStartFrame, durationInFrames],
    [0, -25], // Tilt up slightly
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Combine scales: Entrance only (we do not shrink on exit anymore)
  const finalScale = entranceSpring;
  
  const opacity = interpolate(
    frame,
    [0, 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Twitter Bird SVG Path
  const twitterPath = "M23.953 4.57a10 10 0 01-2.825.775 4.958 4.958 0 002.163-2.723c-.951.555-2.005.959-3.127 1.184a4.92 4.92 0 00-8.384 4.482C7.69 8.095 4.067 6.13 1.64 3.162a4.822 4.822 0 00-.666 2.475c0 1.71.87 3.213 2.188 4.096a4.904 4.904 0 01-2.228-.616v.06a4.923 4.923 0 003.946 4.827 4.996 4.996 0 01-2.212.085 4.936 4.936 0 004.604 3.417 9.867 9.867 0 01-6.102 2.105c-.39 0-.779-.023-1.17-.067a13.995 13.995 0 007.557 2.209c9.053 0 13.998-7.496 13.998-13.985 0-.21 0-.42-.015-.63A9.935 9.935 0 0024 4.59z";

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: 'center', alignItems: 'center' }}>
      <div
        style={{
          width: logoSize,
          height: logoSize,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          // Apply transforms: Move(Fly) -> Rotate(Tilt) -> Scale(Entrance) -> TranslateY(Float)
          transform: `translateX(${flyX}px) translateY(${flyY}px) rotate(${flyRotate}deg) scale(${finalScale}) translateY(${floatOffset}px)`,
          opacity: opacity,
          transition: "none", // Strict frame-based animation
        }}
      >
        <svg
          viewBox="0 0 24 24"
          width="100%"
          height="100%"
          style={{
             overflow: 'visible',
          }}
        >
          {/* Drop Shadow for depth */}
          <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
            <feDropShadow dx="0" dy="4" stdDeviation="2" floodColor="#00000020" />
          </filter>
          
          <path
            d={twitterPath}
            fill={iconColor}
            filter="url(#shadow)"
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default TwitterLogoAnimation;